const x=$json;
const ops=['coupon_validate','coupon_preview','promotion_info'];
if(!ops.includes(x.operation)) throw new Error('Invalid promotion operation');
if(!x.request_id||!x.conversation_id||!x.customer_id) throw new Error('Missing promotion identity');
if(['coupon_validate','coupon_preview'].includes(x.operation) && !x.code) throw new Error('Coupon code required');
if(x.code && (typeof x.code!=='string'||x.code.length<1||x.code.length>100||/[\\r\\n]/.test(x.code))) throw new Error('Invalid coupon code');
return [{json:{
 request_id:String(x.request_id),conversation_id:String(x.conversation_id),customer_id:String(x.customer_id),
 operation:x.operation,code:x.code?x.code.trim():null,cart:x.cart??null,
 caller_context:x.caller_context??{},email:x.email??null
}}];

const x=$json;
// Only bounded coupon operations are permitted.
// No arbitrary REST paths, coupon IDs, discount amounts or eligibility flags from the LLM.
return [{json:{...x,gateway_operation:'coupon_validate'}}];

const r=$json;
if(r.error||r.success===false){
 return [{json:{success:false,request_id:$node['Validate Promotion Contract'].json.request_id,
 operation:$node['Validate Promotion Contract'].json.operation,
 code:$node['Validate Promotion Contract'].json.code,
 eligible:false,error_code:r.error_code||'coupon_validation_failed',
 source:'woocommerce'}}];
}
const v=r.coupon_validation||r.data?.coupon_validation||r;
const safe={
 code:v.code??$node['Validate Promotion Contract'].json.code,
 eligible:v.eligible===true,
 discount_type:v.discount_type??null,
 discount_amount:v.discount_amount??null,
 free_shipping:v.free_shipping===true,
 reason_code:v.reason_code??null
};
return [{json:{success:true,request_id:$node['Validate Promotion Contract'].json.request_id,
operation:$node['Validate Promotion Contract'].json.operation,coupon:safe,
source:'woocommerce',verified_at:new Date().toISOString()}}];
